{"command":"cat << 'EOF' > play.py
import subprocess
import chess
import chess.engine
import sys

def get_fen():
    res = subprocess.run(["./game.py", "status"], capture_output=True, text=True)
    for line in res.stdout.splitlines():
        if line.startswith("FEN: "):
            return line[5:].strip()
    return None

def main():
    e = chess.engine.SimpleEngine.popen_uci('/usr/local/bin/stockfish')

    while True:
        fen = get_fen()
        if not fen:
            print("No FEN found")
            break
        b = chess.Board(fen)
        if b.is_game_over():
            print("Game over")
            break

        print("Evaluating FEN:", fen)
        res = e.play(b, chess.engine.Limit(time=2.0))
        move = res.move.uci()
        print("Playing move:", move)

        res_move = subprocess.run(["./game.py", "move", move], capture_output=True, text=True)
        print(res_move.stdout)
        if "Game over" in res_move.stdout or "You win" in res_move.stdout:
            break

    e.quit()

if __name__ == "__main__":
    main()
